//! W3C SCXML IRP conformance harness for Vertep.
//!
//! - [`manifest`] reads the committed suite (`suite/manifest.xml` and the `ecmascript` and
//!   `null` variants generated by `scripts/import-irp.sh`) and classifies every test as
//!   mandatory, optional or manual.
//! - [`host`] is the in-memory test host: sessions, the SCXML Event I/O Processor, invoked
//!   `scxml` children, autoforward, `done.invoke` and a virtual clock.
//! - [`verdict`] is the pass/fail protocol, [`engine`] the engines under test (the Rust core
//!   now, the Lean oracle later), [`allow`] the expected-deviation allow-list and [`report`] the
//!   run, the gate and the JSON report.
//!
//! The gate runs as `cargo test -p vertep-conformance --release -- --nocapture conformance`
//! and writes `target/conformance-report.json`.

pub mod allow;
pub mod corpus;
pub mod engine;
pub mod host;
pub mod manifest;
pub mod report;
pub mod verdict;

pub use allow::{AllowList, AllowListError, Deviation};
pub use engine::{CaseRun, DocumentRun, EngineUnderTest, RustCore};
pub use host::{Budget, ChartLoader, DirLoader, Host, Stop};
pub use manifest::{Classification, Datamodel, Suite, TestCase};
pub use report::{Record, Report, Status, Totals, run_suite};
pub use verdict::{FailReason, Verdict};

use std::path::PathBuf;

/// Where the JSON report goes: `$CARGO_TARGET_DIR/conformance-report.json`, or the workspace
/// `target/` directory.
pub fn report_path() -> PathBuf {
    let target = std::env::var_os("CARGO_TARGET_DIR")
        .map(PathBuf::from)
        .unwrap_or_else(|| {
            let crate_dir = std::path::Path::new(env!("CARGO_MANIFEST_DIR"));
            crate_dir
                .parent()
                .and_then(std::path::Path::parent)
                .unwrap_or(crate_dir)
                .join("target")
        });
    target.join("conformance-report.json")
}
